class EcommerceApp {
    constructor() {
        this.cart = [];
        this.init();
    }

    init() {
        this.setupEventListeners();
        this.loadCartFromStorage();
        this.updateCartBadge();
    }

    setupEventListeners() {
        // Add to cart buttons
        document.querySelectorAll('.add-to-cart').forEach((button) => {
            button.addEventListener('click', (e) => this.handleAddToCart(e));
        });

        // Newsletter form
        const newsletterForm = document.getElementById('newsletter-form');
        if (newsletterForm) {
            newsletterForm.addEventListener('submit', (e) => this.handleNewsletterSubmit(e));
        }

        // CTA buttons
        document.querySelectorAll('.cta-button').forEach((button) => {
            button.addEventListener('click', (e) => this.handleCTAClick(e));
        });

        // Deal buttons
        document.querySelectorAll('.secondary-button').forEach((button) => {
            button.addEventListener('click', (e) => this.handleDealClick(e));
        });

        // Cart icon
        const cartIcon = document.querySelector('.icon-btn:last-child');
        if (cartIcon) {
            cartIcon.addEventListener('click', () => this.viewCart());
        }
    }

    handleAddToCart(event) {
        const card = event.target.closest('.product-card');
        const name = card.querySelector('.product-name').textContent;
        const price = card.querySelector('.product-price').textContent;

        const product = {
            id: Date.now(),
            name,
            price,
            quantity: 1,
        };

        this.cart.push(product);
        this.saveCartToStorage();
        this.updateCartBadge();
        this.showNotification(`${name} added to cart!`);
    }

    handleNewsletterSubmit(event) {
        event.preventDefault();
        const email = event.target.querySelector('input[type="email"]').value;
        this.showNotification(`Thanks for subscribing! Check your email at ${email}.`, 'success');
        event.target.reset();
    }

    handleCTAClick(event) {
        this.showNotification('Redirecting to shop...', 'info');
    }

    handleDealClick(event) {
        const deal = event.target.closest('.deal-card');
        const title = deal.querySelector('.deal-title').textContent;
        this.showNotification(`Viewing: ${title}`, 'info');
    }

    viewCart() {
        if (this.cart.length === 0) {
            this.showNotification('Your cart is empty', 'info');
        } else {
            const itemCount = this.cart.length;
            const total = this.calculateTotal();
            this.showNotification(
                `You have ${itemCount} item(s) in your cart. Total: ${total}`,
                'info'
            );
        }
    }

    calculateTotal() {
        return this.cart
            .reduce((sum, item) => {
                const price = parseFloat(item.price.replace('$', ''));
                return sum + price * item.quantity;
            }, 0)
            .toFixed(2);
    }

    updateCartBadge() {
        const badge = document.querySelector('.badge');
        if (badge) {
            badge.textContent = this.cart.length;
            badge.style.display = this.cart.length > 0 ? 'flex' : 'none';
        }
    }

    saveCartToStorage() {
        localStorage.setItem('ecommerce_cart', JSON.stringify(this.cart));
    }

    loadCartFromStorage() {
        const saved = localStorage.getItem('ecommerce_cart');
        if (saved) {
            this.cart = JSON.parse(saved);
        }
    }

    showNotification(message, type = 'success') {
        const notification = document.createElement('div');
        notification.className = `notification notification-${type}`;
        notification.textContent = message;

        // Style the notification
        Object.assign(notification.style, {
            position: 'fixed',
            bottom: '2rem',
            right: '2rem',
            padding: '1rem 1.5rem',
            borderRadius: '8px',
            fontSize: '0.95rem',
            fontWeight: '500',
            zIndex: '1000',
            animation: 'slideIn 0.3s ease',
            maxWidth: '400px',
            wordWrap: 'break-word',
        });

        // Apply type-specific styling
        if (type === 'success') {
            notification.style.backgroundColor = '#22c55e';
            notification.style.color = 'white';
        } else if (type === 'info') {
            notification.style.backgroundColor = '#0066cc';
            notification.style.color = 'white';
        } else if (type === 'error') {
            notification.style.backgroundColor = '#ef4444';
            notification.style.color = 'white';
        }

        document.body.appendChild(notification);

        // Remove notification after 3 seconds
        setTimeout(() => {
            notification.style.animation = 'slideOut 0.3s ease';
            setTimeout(() => notification.remove(), 300);
        }, 3000);
    }
}

// Add animations
const style = document.createElement('style');
style.textContent = `
    @keyframes slideIn {
        from {
            transform: translateX(400px);
            opacity: 0;
        }
        to {
            transform: translateX(0);
            opacity: 1;
        }
    }

    @keyframes slideOut {
        from {
            transform: translateX(0);
            opacity: 1;
        }
        to {
            transform: translateX(400px);
            opacity: 0;
        }
    }

    @media (max-width: 480px) {
        .notification {
            right: 1rem !important;
            left: 1rem !important;
            bottom: 1rem !important;
            max-width: none !important;
        }
    }
`;
document.head.appendChild(style);

// Initialize app when DOM is ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        new EcommerceApp();
    });
} else {
    new EcommerceApp();
}
